function routeFromHash(){ return (location.hash.replace(/^#\/?/,'')||'dashboard').split('?')[0]; }
function nav(route){ location.hash=`#/${route}`; }
function currentModule(){ const slug=state.route.startsWith('mod/')?state.route.slice(4):''; return modules.find(m=>m.slug===slug); }
function routeLabel(route){
  if(route==='dashboard')return'Inicio'; if(route==='mi-tesis')return'Mi tesis'; if(route==='viabilidad')return'Viabilidad'; if(route==='matrix')return'Matriz de consistencia';
  if(route==='laboratorio')return'Laboratorio jurídico';if(route==='fuentes')return'Fuentes';if(route==='documentos')return'Documentos';if(route==='drive')return'Google Drive';if(route==='kanban')return'Kanban';if(route==='calendario')return'Cronograma';if(route==='observaciones')return'Observaciones';if(route==='auditoria')return'Auditoría';if(route==='sustentacion')return'Sustentación';if(route==='knowledge')return'Base de conocimiento';if(route==='search')return'Buscador global';if(route==='configuracion')return'Configuración';
  return currentModule()?.label||'Tesis';
}

let automaticSessionPromise=null;
async function ensureAutomaticSession(){
  if(automaticSessionPromise)return automaticSessionPromise;
  automaticSessionPromise=(async()=>{
    const {data:current,error:sessionError}=await sb.auth.getSession();
    if(sessionError)console.warn('No se pudo recuperar la sesión previa:',sessionError);
    if(current?.session){
      state.session=current.session;
      state.user=current.session.user||null;
      return current.session;
    }
    const {data,error}=await sb.auth.signInAnonymously();
    if(error)throw new Error(`No se pudo iniciar el acceso directo: ${error.message}`);
    const session=data?.session||null;
    const user=data?.user||session?.user||null;
    if(!session||!user)throw new Error('Supabase no devolvió una sesión automática válida.');
    state.session=session;
    state.user=user;
    return session;
  })();
  try{return await automaticSessionPromise;}finally{automaticSessionPromise=null;}
}

function renderAccessError(error){
  const message=error?.message||String(error||'Error de conexión');
  app.innerHTML=`<div class="boot"><div class="card pad" style="max-width:620px;margin:auto"><div class="crest">TJ</div><h2>No se pudo conectar con el servicio de datos</h2><p class="muted">${esc(message)}</p><button class="btn primary" id="retryDirectAccess">Reintentar</button></div></div>`;
  const retry=document.querySelector('#retryDirectAccess');
  if(retry)retry.onclick=()=>location.reload();
}

async function recoverAutomaticSession(){
  try{
    await ensureAutomaticSession();
    await ensureProject();
    renderShell();
  }catch(error){
    console.error(error);
    renderAccessError(error);
  }
}

async function init(){
  await ensureAutomaticSession();
  await ensureProject();
  renderShell();
  sb.auth.onAuthStateChange((_event,session)=>{
    state.session=session;
    state.user=session?.user||null;
    if(!state.user)setTimeout(()=>recoverAutomaticSession(),0);
  });
  window.addEventListener('hashchange',()=>{state.route=routeFromHash();if(state.user)renderMain();});
  if('serviceWorker' in navigator){navigator.serviceWorker.register('./sw.js').catch(()=>{});}
}

function renderAuth(){
  app.innerHTML='<div class="boot"><div class="spinner"></div><p>Cargando plataforma…</p></div>';
}

async function ensureProject(){
  if(!state.user)return;
  let {data,error}=await sb.from('tesis_projects').select('*').eq('owner_id',uid()).order('created_at',{ascending:true}).limit(1).maybeSingle();
  if(error){console.error(error);toast('No se pudo cargar el proyecto de tesis.','error');return;}
  if(!data){
    const ins=await sb.from('tesis_projects').insert({owner_id:uid()}).select().single();
    if(ins.error){console.error(ins.error);toast('No se pudo crear el espacio de tesis.','error');return;} data=ins.data;
  }
  state.project=data;
  await sb.from('tesis_profiles').upsert({owner_id:uid(),display_name:state.user.user_metadata?.display_name||'',full_name:state.user.user_metadata?.full_name||''},{onConflict:'owner_id'});
  startReminderLoop();
}

